    { "theme": "Debate regrado sobre temas atuais controversos", "curriculumCode": "EF07LP23", "description": "Aula de debate estruturado sobre aspectos controversos de temas atuais, com pesquisa prévia em jornais e revistas, uso de organizadores textuais argumentativos e respeito ao ponto de vista do outro.", "materials": ["material de pesquisa (jornais, revistas impressas e digitais)", "cronômetro para os turnos de fala"], "steps": ["Escolher um tema controverso e atual para o debate", "Pesquisar previamente argumentos em jornais e revistas", "Organizar a turma em grupos com posições diferentes", "Conduzir o debate regrado, com turnos de fala organizados", "Fechar com uma síntese coletiva considerando os diferentes pontos de vista"] },
    { "theme": "Características dos gêneros para orientar a escrita", "curriculumCode": "EF07LP24", "description": "Aula que reconhece as características de gêneros como comentário digital, entrevista oral e artigo de divulgação científica, para subsidiar a produção textual dos alunos.", "materials": ["exemplos dos gêneros estudados (comentário digital, entrevista, artigo científico)"], "steps": ["Apresentar exemplos de cada gênero à turma", "Identificar em grupos as marcas específicas de cada um", "Comparar as características levantadas em um quadro coletivo", "Discutir como esse conhecimento ajuda na hora de produzir um texto", "Relacionar as características a uma produção futura da turma"] },
    { "theme": "Planejando as características do conto", "curriculumCode": "EF07LP25", "description": "Aula de planejamento da escrita de um conto, definindo ficcionalidade, organização temporal com relações de causa e efeito, tipo de herói e antagonista, tempo e cenário.", "materials": ["ficha de planejamento de conto", "exemplos de contos para consulta"], "steps": ["Retomar exemplos de contos já lidos pela turma", "Discutir os elementos que compõem um conto (herói, antagonista, cenário)", "Preencher em duplas uma ficha de planejamento do próprio conto", "Trocar as fichas entre duplas para sugestões de melhoria", "Ajustar o planejamento antes de iniciar a produção do conto"] },
    { "theme": "Como se organiza um artigo de divulgação científica", "curriculumCode": "EF07LP26", "description": "Aula sobre a organização interna de artigos de divulgação científica, observando o léxico típico da área tratada e as implicações do portador e da situação comunicativa.", "materials": ["artigos de divulgação científica de áreas diferentes"], "steps": ["Apresentar artigos de divulgação científica de áreas distintas", "Identificar palavras e expressões típicas de cada área", "Discutir como o portador do texto influencia a linguagem usada", "Comparar a organização interna dos artigos apresentados", "Sistematizar coletivamente as observações sobre o gênero"] },
    { "theme": "Substituição e elipse na coesão textual", "curriculumCode": "EF07LP27", "description": "Aula sobre estratégias de coesão por substituição de um termo por outro e por elipse, observando como esses recursos evitam repetições e favorecem a clareza do texto.", "materials": ["texto com repetições e elipses marcadas", "dicionário de sinônimos"], "steps": ["Ler um texto e destacar palavras repetidas em excesso", "Buscar termos para substituir as repetições identificadas", "Identificar trechos em que um termo foi omitido por elipse", "Reescrever trechos aplicando substituição e elipse", "Discutir em duplas como essas estratégias melhoram a clareza do texto"] },
    { "theme": "Articuladores textuais na construção da argumentação", "curriculumCode": "EF07LP28", "description": "Aula sobre o reconhecimento e o uso de articuladores textuais de tempo, espaço, relações lógico-semânticas e argumentação, como recursos para conectar diferentes trechos de um texto.", "materials": ["texto com articuladores textuais destacados", "lista de conectivos organizada por função"], "steps": ["Ler um texto argumentativo e destacar os articuladores presentes", "Classificar os articuladores encontrados por função", "Substituir um articulador por outro e discutir a mudança de sentido", "Propor um exercício de completar lacunas com articuladores adequados", "Corrigir coletivamente, comentando os efeitos de cada escolha"] },
    { "theme": "Coerência entre as partes do texto", "curriculumCode": "EF07LP29", "description": "Aula sobre como articular as diferentes partes de um texto de forma coerente, evitando problemas de compreensão durante a produção escrita.", "materials": ["trecho de texto com problema de coerência para análise", "folha para reescrita"], "steps": ["Apresentar um trecho de texto com falhas de coerência entre parágrafos", "Discutir em grupo por que o trecho dificulta a compreensão", "Propor coletivamente uma reescrita que resolva o problema", "Aplicar a mesma análise a um texto produzido pela própria turma", "Revisar em duplas, verificando a articulação entre as partes"] },
    { "theme": "Discurso direto e indireto na narrativa", "curriculumCode": "EF07LP30", "description": "Aula sobre as diferentes formas de introduzir a fala de outra pessoa em textos narrativos — discurso direto e indireto, pontuação e posição do verbo de elocução — e os efeitos de sentido de cada escolha.", "materials": ["trechos narrativos com discurso direto e indireto", "quadro branco"], "steps": ["Apresentar um trecho narrativo com discurso direto e outro com discurso indireto", "Comparar a pontuação e a posição do verbo de elocução em cada caso", "Discutir os efeitos de sentido produzidos por cada forma de discurso", "Propor a reescrita de um trecho, transformando discurso direto em indireto", "Corrigir coletivamente destacando as mudanças observadas"] },
    { "theme": "Pontuação expressiva e efeitos de sentido", "curriculumCode": "EF07LP31", "description": "Aula que analisa como diferentes formas de pontuar um mesmo trecho de texto alteram seu efeito de sentido, com destaque para a pontuação expressiva.", "materials": ["um mesmo trecho de texto pontuado de formas diferentes", "quadro branco"], "steps": ["Apresentar um mesmo trecho pontuado de duas ou três formas diferentes", "Ler cada versão em voz alta, destacando a diferença de entonação", "Discutir em grupos como a pontuação muda o sentido ou a emoção do trecho", "Propor que os alunos repontuem um trecho para obter um efeito específico", "Compartilhar e comparar as versões produzidas pela turma"] },
    { "theme": "Paragrafação em artigos de divulgação científica", "curriculumCode": "EF07LP32", "description": "Aula de análise dos critérios de paragrafação usados na elaboração de um artigo de divulgação científica, observando os efeitos de sentido que produzem.", "materials": ["artigo de divulgação científica com parágrafos numerados"], "steps": ["Ler um artigo de divulgação científica observando a divisão em parágrafos", "Identificar a ideia central de cada parágrafo", "Discutir por que o autor optou por essa divisão específica", "Propor a reorganização de um parágrafo extenso em dois menores", "Comparar coletivamente os efeitos da nova paragrafação"] },
    { "theme": "Vírgula nas enumerações", "curriculumCode": "EF07LP33", "description": "Aula sobre o uso da vírgula em enumerações, aplicada em situações de produção e revisão de textos.", "materials": ["frases com enumerações sem pontuação", "quadro branco"], "steps": ["Apresentar frases com listas de itens sem pontuação adequada", "Explicar a regra de uso da vírgula em enumerações", "Propor exercícios de pontuação de frases com enumerações", "Revisar em duplas um texto próprio observando esse uso da vírgula", "Corrigir coletivamente os casos mais recorrentes de erro"] },
    { "theme": "Vírgula entre sujeito e verbo: o que evitar", "curriculumCode": "EF07LP34", "description": "Aula sobre o reconhecimento e o uso correto da vírgula, com foco na regra de não separar sujeito e verbo, mesmo quando o sujeito vem posposto ou há inversão na ordem da oração.", "materials": ["frases com sujeito posposto ou ordem invertida", "quadro branco"], "steps": ["Apresentar frases com sujeito posposto ou ordem invertida", "Discutir coletivamente por que não se deve separar sujeito e verbo com vírgula", "Propor exercícios de identificação de erros desse tipo em frases dadas", "Revisar em duplas um texto próprio observando essa regra", "Corrigir coletivamente destacando os casos mais comuns de erro"] },
    { "theme": "Escolhas lexicais e intenção de sentido", "curriculumCode": "EF07LP35", "description": "Aula de análise das escolhas de palavras feitas em textos produzidos pelos próprios alunos, verificando se estão adequadas às intenções de significação pretendidas.", "materials": ["textos produzidos pelos alunos em aula anterior", "dicionário"], "steps": ["Retomar um texto produzido pela turma em aula anterior", "Destacar palavras-chave escolhidas pelo autor do texto", "Discutir em duplas se as palavras escolhidas transmitem a intenção pretendida", "Propor substituições para palavras que não estejam adequadas", "Comparar as versões antes e depois dos ajustes lexicais"] },
    { "theme": "Vocabulário próprio de cada disciplina", "curriculumCode": "EF07LP36", "description": "Aula que identifica expressões típicas de um gênero textual e de uma área do conhecimento em textos de diferentes disciplinas.", "materials": ["textos de disciplinas diferentes (ciências, história, geografia)"], "steps": ["Apresentar trechos de textos de disciplinas diferentes", "Destacar palavras e expressões típicas de cada área", "Discutir em grupos por que cada disciplina usa um vocabulário próprio", "Elaborar um pequeno glossário coletivo com termos identificados", "Relacionar o vocabulário encontrado a um projeto interdisciplinar em curso"] },
    { "theme": "Ironia, humor e crítica nos textos", "curriculumCode": "EF07LP37", "description": "Aula de reconhecimento e análise de recursos linguístico-discursivos usados para construir ironia, humor ou crítica nos textos estudados.", "materials": ["textos com ironia ou humor (crônicas, charges, tiras)"], "steps": ["Ler um texto com forte presença de ironia ou humor", "Identificar as expressões responsáveis pelo efeito irônico ou humorístico", "Discutir em grupo a crítica que o texto pretende fazer", "Comparar com um segundo texto de recurso semelhante", "Registrar coletivamente os recursos linguísticos identificados"] },
    { "theme": "Sentido denotativo e conotativo das palavras", "curriculumCode": "EF07LP38", "description": "Aula de análise dos efeitos de sentido produzidos pelo emprego de palavras em sentido denotativo e conotativo, observando suas implicações discursivas.", "materials": ["frases e trechos com palavras em sentido denotativo e conotativo", "quadro branco"], "steps": ["Apresentar uma palavra em uma frase de sentido literal e outra de sentido figurado", "Discutir a diferença de efeito entre as duas frases", "Propor a identificação de sentido denotativo e conotativo em um texto curto", "Pedir que os alunos criem frases próprias explorando os dois sentidos", "Compartilhar e comentar as frases produzidas pela turma"] },
    { "theme": "Recursos gráficos na construção do texto", "curriculumCode": "EF07LP39", "description": "Aula sobre o uso de recursos gráfico-textuais — recuos, alinhamento, espaçamento, tipo e tamanho de letra, estilo e cores — na construção de sentido em textos escritos.", "materials": ["exemplos de textos com formatação variada", "computador ou tablet (opcional)"], "steps": ["Apresentar dois textos com formatações gráficas diferentes", "Discutir como recuos, alinhamento e estilo de letra influenciam a leitura", "Propor que os alunos reformatem um texto simples usando recursos diferentes", "Comparar as versões produzidas e discutir os efeitos obtidos", "Sistematizar coletivamente quando cada recurso gráfico é mais adequado"] },
    { "theme": "As variedades da Língua Portuguesa", "curriculumCode": "EF07LP40", "description": "Aula sobre a existência de variedades linguísticas determinadas por classe social, gênero, idade, escolaridade, profissão, região e influências dos povos indígenas, africanos e europeus.", "materials": ["gravações ou trechos escritos com variedades linguísticas diferentes", "mapa do Brasil (opcional)"], "steps": ["Apresentar exemplos de fala ou escrita de diferentes regiões e grupos sociais", "Discutir em grupo os fatores que explicam essas diferenças", "Relacionar algumas variedades a influências indígenas, africanas e europeias", "Elaborar um cartaz coletivo com exemplos de variedades linguísticas", "Refletir sobre a riqueza da diversidade linguística do português brasileiro"] },
    { "theme": "Quando usar cada variedade linguística", "curriculumCode": "EF07LP41", "description": "Aula sobre o reconhecimento das situações comunicativas mais apropriadas para cada variedade linguística, valorizando-as sem hierarquizá-las.", "materials": ["situações comunicativas variadas descritas em fichas"], "steps": ["Apresentar diferentes situações comunicativas (entrevista formal, conversa entre amigos, mensagem de texto)", "Discutir qual variedade linguística seria mais adequada a cada situação", "Propor que os alunos reescrevam uma mesma mensagem em registros diferentes", "Debater por que nenhuma variedade é superior à outra", "Fechar com uma reflexão coletiva sobre respeito à diversidade linguística"] },
    { "theme": "Pronomes: usos e efeitos de sentido", "curriculumCode": "EF07LP42", "description": "Aula sobre os usos e funções dos pronomes (pessoais, possessivos, demonstrativos, indefinidos, interrogativos e relativos), analisando os efeitos de sentido de seu emprego em textos.", "materials": ["texto com pronomes destacados", "quadro branco"], "steps": ["Apresentar um texto e destacar os pronomes presentes", "Classificar coletivamente os pronomes encontrados por tipo", "Discutir a que palavras cada pronome se refere no texto", "Propor a substituição de um pronome por outro e discutir a mudança de sentido", "Corrigir exercícios de identificação de pronomes em novos textos"] },
    { "theme": "Períodos simples e compostos", "curriculumCode": "EF07LP43", "description": "Aula sobre o processo de formação de períodos simples e compostos, reconhecendo diferenças de efeito de sentido entre eles.", "materials": ["frases simples e compostas para análise", "quadro branco"], "steps": ["Apresentar exemplos de períodos simples e compostos", "Discutir a diferença estrutural entre os dois tipos de período", "Propor a transformação de períodos simples em compostos, unindo ideias", "Discutir em grupo como a junção altera o efeito de sentido", "Corrigir coletivamente os exercícios propostos"] },
    { "theme": "Sujeito e predicado no sintagma verbal", "curriculumCode": "EF07LP44", "description": "Aula de análise da formação de sintagmas verbais, identificando os termos essenciais da oração — sujeito e predicado — para compreender seus usos no texto.", "materials": ["frases para identificação de sujeito e predicado", "quadro branco"], "steps": ["Apresentar frases simples para identificação de sujeito e predicado", "Explicar coletivamente como reconhecer cada termo essencial", "Propor exercícios de sublinhar sujeito e predicado em frases variadas", "Discutir em duplas casos mais desafiadores de identificação", "Corrigir coletivamente destacando os erros mais comuns"] },
    { "theme": "Tipos de sujeito e concordância verbal", "curriculumCode": "EF07LP45", "description": "Aula sobre as funções que diferentes tipos de sujeito exercem em relação às flexões do verbo, observando efeitos de sentido e variedades linguísticas do português falado no Brasil.", "materials": ["frases com diferentes tipos de sujeito", "quadro branco"], "steps": ["Apresentar frases com sujeitos simples, composto e oculto", "Discutir como cada tipo de sujeito influencia a flexão verbal", "Relacionar exemplos de concordância verbal a variedades linguísticas faladas no Brasil", "Propor exercícios de classificação do tipo de sujeito em frases variadas", "Corrigir coletivamente, comentando os efeitos de sentido observados"] },
    { "theme": "Ordem direta e inversa da oração", "curriculumCode": "EF07LP46", "description": "Aula de análise das possibilidades de ordem direta e inversa da oração em Língua Portuguesa, observando os efeitos de sentido produzidos por cada escolha.", "materials": ["frases em ordem direta e inversa para comparação", "quadro branco"], "steps": ["Apresentar uma frase em ordem direta e a mesma frase em ordem inversa", "Discutir a diferença de efeito entre as duas versões", "Propor que os alunos reescrevam frases próprias invertendo a ordem", "Comparar os efeitos obtidos nas frases produzidas pela turma", "Fechar com uma síntese sobre quando usar cada ordem na produção de texto"] },
    { "theme": "Acentuação gráfica em monossílabos tônicos", "curriculumCode": "EF07LP47", "description": "Aula sobre as convenções de acentuação gráfica de palavras, com foco na função do acento tônico em monossílabos.", "materials": ["lista de monossílabos tônicos e átonos", "quadro branco"], "steps": ["Apresentar exemplos de monossílabos acentuados e não acentuados", "Explicar a regra de acentuação para monossílabos tônicos", "Propor exercícios de identificação e acentuação de monossílabos em frases", "Corrigir coletivamente destacando os casos de dúvida frequente", "Fechar com um ditado de frases contendo monossílabos tônicos"] },
    { "theme": "Acentuação de oxítonas, paroxítonas e proparoxítonas", "curriculumCode": "EF07LP48", "description": "Aula prática sobre o emprego correto da acentuação gráfica em palavras oxítonas, paroxítonas e proparoxítonas, a partir das regularidades estudadas.", "materials": ["lista de palavras oxítonas, paroxítonas e proparoxítonas", "quadro branco"], "steps": ["Retomar a classificação das palavras quanto à posição da sílaba tônica", "Explicar as regras de acentuação para cada classificação", "Propor exercícios de acentuação de uma lista de palavras variadas", "Corrigir coletivamente, destacando os erros mais frequentes", "Fechar com um jogo de acentuação em duplas"] },
    { "theme": "Regularidades contextuais da ortografia", "curriculumCode": "EF07LP49", "description": "Aula sobre a escrita convencional de palavras que dependem do contexto para a escolha da letra correta, como R e RR, M e N em finais de sílaba, e vogais em sílabas nasais.", "materials": ["lista de palavras com regularidades contextuais", "quadro branco"], "steps": ["Apresentar pares de palavras que exemplificam as regularidades contextuais", "Explicar coletivamente como o contexto determina a letra correta", "Propor exercícios de completar palavras usando as regras discutidas", "Revisar em duplas um texto próprio observando essas regularidades", "Corrigir coletivamente os casos mais recorrentes de erro"] },
    { "theme": "Regularidades morfossintáticas na ortografia", "curriculumCode": "EF07LP50", "description": "Aula de análise de palavras com regularidades morfossintáticas, relacionando a forma gramatical (infinitivo, gerúndio, tempos verbais) às convenções ortográficas correspondentes.", "materials": ["lista de verbos em diferentes formas e tempos", "quadro branco"], "steps": ["Apresentar verbos no infinitivo, gerúndio e em diferentes tempos verbais", "Discutir coletivamente a relação entre a forma gramatical e a grafia final", "Propor exercícios de completar verbos com a terminação correta", "Revisar em duplas frases com verbos flexionados", "Corrigir coletivamente, sistematizando as regras observadas"] },
    { "theme": "Palavras irregulares: S, Z, X, Ç e outras grafias", "curriculumCode": "EF07LP51", "description": "Aula sobre a escrita convencional de palavras de uso frequente que não seguem regras fixas, envolvendo letras como S, C, Z, SS, X, Ç, XC, SC e SÇ.", "materials": ["lista de palavras irregulares frequentes", "dicionário"], "steps": ["Apresentar uma lista de palavras irregulares de uso comum", "Discutir por que essas palavras não seguem uma regra fixa de grafia", "Propor exercícios de completar as palavras com a letra correta", "Consultar o dicionário para conferir grafias em caso de dúvida", "Elaborar coletivamente uma lista de palavras irregulares para memorização"] }
